1: import ts from "typescript";
2: import fs from "node:fs";
3: import path from "node:path";
4: import { createHash } from "node:crypto";
5: import { jsonType } from "./annotate.mjs";
6: 
7: export const sha256 = value => createHash("sha256").update(value).digest("hex");
8: export function compareEmission(raw, refined, root) {
9:   const configPath = path.join(root, "tsconfig.app.json");
10:   const configBytes = fs.readFileSync(configPath, "utf8");
11:   const config = ts.parseConfigFileTextToJson(configPath, configBytes);
12:   if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, "\n"));
13:   const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, root);
14:   if (parsed.errors.length) throw new Error(ts.formatDiagnosticsWithColorAndContext(parsed.errors, {
15:     getCurrentDirectory: () => root, getCanonicalFileName: p => p, getNewLine: () => "\n",
16:   }));
17:   const overrides = { noEmit: false, allowImportingTsExtensions: false, removeComments: true,
18:     sourceMap: false, inlineSourceMap: false };
19:   const options = { ...parsed.options, ...overrides };
20:   const name = path.join(root, "codegen/gotypes.gen.ts");
21:   function emit(text) {
22:     const host = ts.createCompilerHost(options), original = host.readFile.bind(host);
23:     host.readFile = p => path.resolve(p) === name ? text : original(p);
24:     const program = ts.createProgram([name], options, host);
25:     const source = program.getSourceFile(name);
26:     if (!source || source.statements.some(s => ts.isImportDeclaration(s) || ts.isImportEqualsDeclaration(s) ||
27:       (ts.isExportDeclaration(s) && s.moduleSpecifier))) throw new Error("Generated module must be import-free");
28:     const diagnostics = ts.getPreEmitDiagnostics(program);
29:     const outputs = [];
30:     const result = program.emit(source, (p, value) => {
31:       if (p.endsWith(".js")) outputs.push(value);
32:     });
33:     if (diagnostics.length || result.diagnostics.length || result.emitSkipped || outputs.length !== 1 || !outputs[0])
34:       throw new Error("Generated module emission failed: " + ts.formatDiagnostics([...diagnostics, ...result.diagnostics], {
35:         getCurrentDirectory: () => root, getCanonicalFileName: p => p, getNewLine: () => "\n",
36:       }));
37:     return outputs[0];
38:   }
39:   const before = emit(jsonType + raw), after = emit(refined);
40:   if (before !== after) throw new Error("Generated JavaScript changed after annotation");
41:   return { compiler: ts.version, config_sha256: sha256(configBytes), options, overrides,
42:     javascript_sha256: sha256(before), javascript_bytes: Buffer.byteLength(before), identical: true };
43: }
